/* Offline application; all data is generated from the project's PDF files. */
(function () {
  'use strict';
  const D=window.PLAN_DATA, M=window.PlanModel;
  if(!D||!M){document.getElementById('content').textContent='Daten fehlen. Bitte Aktualisieren.cmd ausführen.';return;}
  const $=s=>document.querySelector(s), e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const nf=new Intl.NumberFormat('de-DE',{maximumFractionDigits:0});
  const dec=(v,k=2)=>v==null?'–':new Intl.NumberFormat('de-DE',{minimumFractionDigits:k,maximumFractionDigits:k}).format(v);
  const num=v=>v==null?'–':nf.format(v), euro=v=>v==null?'–':`${num(v)} €`, teuro=v=>v==null?'–':`${dec(v/1000,2)} T€`;
  const pct=v=>v==null?'–':`${dec(v,2)} %`, sign=v=>`${v>0?'+':''}${euro(v)}`;
  const current=D.reports[D.latestDetailedPeriod], defaults=M.defaults(D), presets=M.presets(defaults,current);
  const sections=[['overview','Überblick','grid'],['market','Markt & Kosten','chart'],['operations','Betrieb & Personal','factory'],['finance','Finanzen','wallet'],['scenario','Szenario-Labor','sliders'],['recommendations','Empfehlungen','spark'],['sources','Quellen & Daten','book']];
  const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chart:'<path d="M3 20V4m0 16h18M7 15l4-5 4 2 6-8"/>',factory:'<path d="M3 21V10l6 3V8l6 4V3h5v18H3Zm3-4h2m3 0h2m3 0h2"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18m-5 5h5v4h-5z"/>',sliders:'<path d="M5 3v9m0 5v4m7-18v3m0 5v10m7-18v12m0 5v1"/><circle cx="5" cy="14" r="2"/><circle cx="12" cy="8" r="2"/><circle cx="19" cy="17" r="2"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',book:'<path d="M12 5c-3-2-6-2-10-1v16c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v16"/>'};
  const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
  const src=(doc,page=1,label)=>doc?`<button class="source-link" data-source="${e(doc)}" data-page="${page}">${e(label||doc)} · S. ${page}</button>`:'<span class="small muted">Passende Periodenquelle fehlt</span>';
  const source=(r,part,label)=>src(r.doc,r.pages[part]||1,label);
  const foot=(r,part,label)=>`<div class="source-foot">${source(r,part,label)}</div>`;
  const info=t=>`<span class="info" data-tip="${e(t)}" tabindex="0" aria-label="${e(t)}">i</span>`;
  const row=(label,value,cls='')=>`<div class="metric-row ${cls}"><span>${label}</span><strong>${value}</strong></div>`;
  const tag=(text,cls='actual')=>`<span class="tag ${cls}">${text}</span>`;
  let selected=D.latestPeriod, view=location.hash.slice(1)||'overview', scenario=M.copy(defaults), scenarioName='Mein Szenario', savedIndex='';
  let scenarios=[];
  try {scenarios=JSON.parse(localStorage.getItem('u1-scenarios-v1')||'[]');if(!Array.isArray(scenarios))scenarios=[];}catch{}
  function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
  function report(){return D.reports[selected];}
  function heading(title,description,extra=''){return `<div class="page-heading"><div><div class="eyebrow">UNTERNEHMEN 1 · ${view==='scenario'||view==='recommendations'?`ENTSCHEIDUNG P${D.nextNews?.period||D.latestPeriod+1}`:`AUSWERTUNG P${selected}`}</div><h1>${title}</h1><p class="subheading">${description}</p></div><div class="heading-tools">${extra||tag('Berichtswerte')+tag('Berechnung','model')}</div></div>`;}
  function card(title,sub,content,action=''){return `<section class="card"><div class="card-top"><div class="card-title"><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${content}</section>`;}
  function unavailable(){return `${heading(`Periode ${selected}`, 'Für diese Periode liegt eine Gewinnübersicht, aber kein eigener U1-Detailbericht vor.')}<div class="callout neutral">Die fehlenden Umsatz-, Personal- und Produktionsdaten werden nicht ergänzt. Der Gewinn stammt aus ${src(D.profitDoc)}.</div><div class="grid equal">${card('Periodenüberschuss','Aus der marktweiten Gewinnübersicht',`<div class="mini-value">${euro(D.profits[selected]?.[0])}</div>`)}${card('Gewinnverlauf','P3 ist nur über die Gewinnübersicht dokumentiert.',profitChart())}</div>`;}
  function kpi(label,value,caption,key,tone=''){return `<button class="kpi" data-detail="${key}"><span class="kpi-label">${label}<span aria-hidden="true">↗</span></span><span class="kpi-value">${value}</span><span class="kpi-caption ${tone}">${caption}</span></button>`;}
  function profitChart(){
    const ps=Object.keys(D.profits).map(Number).sort((a,b)=>a-b), values=ps.map(p=>D.profits[p][0]), max=Math.max(...Object.values(D.profits).flat())*1.15;
    const width=560,height=210,left=38,bottom=174,plot=138;
    let out=`<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Periodenüberschuss U1 und Branche über die Zeit">`;
    [0,.5,1].forEach(k=>{const y=bottom-k*plot;out+=`<line x1="38" y1="${y}" x2="548" y2="${y}" stroke="#e6ede3"/><text x="28" y="${y+3}" text-anchor="end" class="axis-label">${num(max*k/1000)}</text>`;});
    const step=490/ps.length;
    ps.forEach((p,i)=>{const avg=D.profits[p].reduce((a,b)=>a+b,0)/10,x=left+i*step+step/2;
      out+=`<g tabindex="0" role="button" data-period="${p}" aria-label="Periode ${p} auswählen" data-tip="P${p}: U1 ${euro(values[i])}; Branche im Mittel ${euro(avg)}${D.reports[p]?'':' · U1-Detailbericht fehlt'}"><rect x="${x-27}" y="${bottom-values[i]/max*plot}" width="27" height="${Math.max(1,values[i]/max*plot)}" rx="4" fill="${p===selected?'#18735b':'#a2c6b0'}"/><rect x="${x+5}" y="${bottom-avg/max*plot}" width="22" height="${avg/max*plot}" rx="4" fill="#d5e1cc"/><text x="${x-12}" y="${bottom-values[i]/max*plot-8}" text-anchor="middle" class="chart-value">${dec(values[i]/1000,1)}</text><text x="${x}" y="194" text-anchor="middle">P${p}${D.reports[p]?'':'*'}</text></g>`;});
    return out+'</svg><div class="legend"><span><i style="background:#18735b"></i>U1 · T€</span><span><i style="background:#d5e1cc"></i>Branchendurchschnitt · T€</span><span>* Kein U1-Detailbericht</span></div>';
  }
  function rankChart(){
    const totals=Array.from({length:10},(_,i)=>({company:i+1,total:Object.entries(D.profits).filter(([p])=>+p<=selected).reduce((sum,[,v])=>sum+v[i],0)})).sort((a,b)=>b.total-a.total);
    const max=totals[0].total;
    return `<svg class="chart" viewBox="0 0 430 260" role="img" aria-label="Kumulierte Gewinne im Branchenvergleich">${totals.map((c,i)=>`<g data-tip="${c.company===10?'Oma':`U${c.company}`}: ${euro(c.total)} kumuliert; Rang ${i+1}" tabindex="0"><text x="0" y="${20+i*24}">${i+1}.</text><text x="27" y="${20+i*24}" ${c.company===1?'class="chart-value"':''}>${c.company===10?'Oma':`U${c.company}`}</text><rect x="68" y="${9+i*24}" width="${c.total/max*278}" height="14" rx="3" fill="${c.company===1?'#19735b':'#dce6d7'}"/><text x="${Math.min(380,76+c.total/max*278)}" y="${20+i*24}" class="axis-label">${dec(c.total/1000,1)}</text></g>`).join('')}</svg>`;
  }
  function overview(){
    const r=report();if(!r)return unavailable();const m=r.metrics;
    const pp=D.profits[selected-1]?.[0];
    return heading('U1 im Überblick','Ergebnis, Marktposition und Handlungsbedarf des letzten Halbjahres.')+
      `<div class="hero-strip"><span class="hero-icon" aria-hidden="true">↗</span><div class="hero-content"><strong>${m.operatingProfit>0?'Profitabel. ':''}${m.utilization>=99?'Kapazität ausgelastet.':'Spielraum in der Produktion.'}</strong><p>${euro(m.profit)} Überschuss · ${pct(m.margin)} Umsatzrendite · ${m.overdraft?'Überziehungskredit vorhanden':'Kein Überziehungskredit'}. Die nächste Entscheidung braucht eine belastbare Absatz- und Personalplanung.</p></div><button class="link-button" data-nav="recommendations">Empfehlungen ansehen →</button></div>`+
      `<div class="kpi-grid">${kpi('Umsatz',teuro(m.revenue),`${num(m.retailUnits)} Shop + ${num(r.decisions.wholesale||0)} Großhandel`,'revenue')}${kpi('Periodenüberschuss',teuro(m.profit),pp?`${dec((m.profit/pp-1)*100,1)} % gegenüber P${selected-1}`:'Ergebnis nach Steuern','profit','positive')}${kpi('Kassenbestand',teuro(m.cash),`${teuro(m.credit+m.overdraft)} Kredite`,'cash')}${kpi('Anlagenauslastung',pct(m.utilization),`${num(m.production)} von ${num(m.capacity)} Zelten`,'production',m.utilization>=99?'warning':'')}${kpi('Marktanteil',pct(m.marketShare),`${euro(r.decisions.price)} Shop-Preis`,'market')}${kpi('Planungsqualität',dec(m.planningQuality),`${pct(m.planningDeviation)} Abweichung zum Plan`,'planning','warning')}</div>`+
      `<div class="grid two">${card('Ergebnis über die Perioden','Periodenüberschuss · U1 und Branche',profitChart(),tag('P1–P'+D.latestPeriod,'model'))}${card('Kumulierte Marktposition','Gewinnsumme bis zur gewählten Periode · T€',rankChart())}</div>`+
      `<div class="grid two">${card('Drei Umsatzzahlen. Drei Bedeutungen.','Die Planungsbewertung nutzt das Marktpotenzial, nicht den realisierten Gesamtumsatz.',row('Geplanter Shop-Umsatz',teuro(m.plannedRevenue))+row('Potenzieller Shop-Umsatz '+info('Berichtszeile „Ist-Wert“ im Planvergleich = potenzielle Shop-Menge × Preis. Nicht der tatsächlich erzielte Shop-Umsatz.'),teuro(m.potentialRevenue))+row('Tatsächlicher Shop-Umsatz',teuro(m.retailRevenue))+row('Großhandelsumsatz',teuro(m.wholesaleRevenue))+row('Gesamtumsatz',teuro(m.revenue),'emphasis')+foot(r,'income'))}${card('Was jetzt Aufmerksamkeit braucht','Klicke für die zugrunde liegenden Werte.',`<div class="metric-row"><span>Personalbedarf</span><button class="link-button" data-nav="operations">${dec(m.temporaryFte,2)} Zeitarbeitskräfte →</button></div><div class="metric-row"><span>Großhandelsentscheidung</span><button class="link-button" data-nav="scenario">Kapazität & Mehrkosten prüfen →</button></div><div class="metric-row"><span>Datenlücken</span><button class="link-button" data-nav="sources">P3-Detailbericht / P4-News fehlen →</button></div><div class="callout neutral">Ein höherer Preis kann eine gute Marge ermöglichen. Ohne bekannte Nachfragefunktion lässt sich daraus kein optimaler Preis berechnen.</div>`)}</div>`;
  }
  function costTable(r){const u=r.costUnits;return `<div class="table-wrap"><table><thead><tr><th>Baustein</th><th class="num">€ / Zelt</th><th>Einordnung</th></tr></thead><tbody>${[
    ['Material inkl. Betriebsstoffe',(u.parts||0)+(u.supplies||0),'Mengenabhängig'],
    ['Fertigung direkt inkl. Zeitarbeit',u.directLabour,'Eigene Gehälter fix; Zeitarbeit anteilig'],
    ['Fertigungsgemeinkosten',u.factoryOverhead,'Anlagen / Gemeinkosten; inkl. Abschreibung'],
    ['Herstellkosten',r.metrics.manufacturingUnit,'Summe Produktionskosten'],
    ['Forschung & Entwicklung',u.research,'Budget, auf Verkäufe verteilt'],
    ['Werbung / Verkaufsförderung',u.advertising,'Budget, auf Verkäufe verteilt'],
    ['Vertriebsgemeinkosten',u.sellingOverhead,'Überwiegend feste Personal- und Raumkosten'],
    ['Einkauf / Verwaltung',(u.adminDirect||0)+(u.adminOverhead||0),'Gemischt: fixe und umsatzabhängige Kosten'],
    ['Selbstkosten',r.metrics.selfCostUnit,'Volle durchschnittliche Kosten']
    ].map(([l,v,type])=>`<tr class="${l==='Selbstkosten'||l==='Herstellkosten'?'cost-total':''}"><td class="wrap">${l}</td><td class="num">${dec(v)}</td><td class="wrap small muted">${type}</td></tr>`).join('')}</tbody></table></div>`;}
  function scatter(r){
    const cs=r.competitors,xmin=Math.min(...cs.map(c=>c.price))-8,xmax=Math.max(...cs.map(c=>c.price))+8,ymax=Math.max(...cs.map(c=>c.units))*1.15,ymin=0;
    const X=v=>50+(v-xmin)/(xmax-xmin)*470,Y=v=>210-(v-ymin)/(ymax-ymin)*180;
    let svg='<svg class="chart" viewBox="0 0 560 250" role="img" aria-label="Preis und Shop-Absatz der Wettbewerber">';
    [0,.5,1].forEach(v=>{const y=Y(ymax*v);svg+=`<line x1="50" y1="${y}" x2="530" y2="${y}" stroke="#e7eee4"/><text x="40" y="${y+4}" text-anchor="end">${num(ymax*v)}</text>`;});
    for(let v=Math.ceil(xmin/10)*10;v<xmax;v+=10)svg+=`<text x="${X(v)}" y="232" text-anchor="middle">${num(v)} €</text>`;
    cs.forEach(c=>{const x=X(c.price),y=Y(c.units);svg+=`<g tabindex="0" role="button" data-company="${c.company}" aria-label="U${c.company}: ${num(c.units)} Zelte zu ${euro(c.price)}; Details öffnen" data-tip="U${c.company}: ${num(c.units)} Zelte · ${euro(c.price)} · Technologie ${dec(c.technology)}"><circle cx="${x}" cy="${y}" r="${c.company===1?10:7}" fill="${c.company===1?'#19735b':'#aec7a0'}" stroke="white" stroke-width="2"/><text x="${x+12}" y="${y+3}" class="${c.company===1?'chart-value':'axis-label'}">U${c.company}</text></g>`;});
    return svg+'</svg>';
  }
  function market(){const r=report();if(!r)return unavailable();const m=r.metrics;
    const costs=[m.manufacturingUnit,Math.max(0,m.selfCostUnit-m.manufacturingUnit)],sum=costs.reduce((a,b)=>a+b,0);
    return heading('Markt & Stückkosten','Preisposition, Wettbewerb und die Kosten hinter jedem verkauften Zelt.')+
      `<div class="grid equal">${card('Preis und Absatz','Jeder Punkt ist ein Unternehmen. Anklicken für Details.',scatter(r),tag('Shop'))}${card('Die Kosten eines Zeltes','Vergangenheitswerte; keine Grenzkosten für den nächsten Auftrag.',`<div class="flex-between"><div><span class="mini-label">Herstellkosten</span><div class="mini-value">${dec(m.manufacturingUnit)} €</div></div><div class="right"><span class="mini-label">Selbstkosten</span><div class="mini-value">${dec(m.selfCostUnit)} €</div></div></div><div class="cost-stack"><button style="width:${costs[0]/sum*100}%;background:#19735b" data-detail="costs" aria-label="Herstellkosten aufschlüsseln" data-tip="Herstellkosten: ${dec(costs[0])} €"></button><button style="width:${costs[1]/sum*100}%;background:#c5dca5" data-detail="costs" aria-label="Übrige Selbstkosten aufschlüsseln" data-tip="F&E, Vertrieb und Verwaltung: ${dec(costs[1])} €"></button></div><div class="legend"><span><i style="background:#19735b"></i>Produktion</span><span><i style="background:#c5dca5"></i>F&E / Vertrieb / Verwaltung</span></div><div class="callout">${euro(defaults.wholesalePrice)} Großhandelspreis in P${D.nextNews?.period||'?'}, verglichen mit ${dec(m.selfCostUnit)} € historischen Selbstkosten: Das allein entscheidet nicht über den Zusatzauftrag. Zusätzliche Kosten und entgangener Shop-Absatz müssen gemeinsam gerechnet werden.</div>${source(r,'costs')}`)}</div>`+
      card('Wettbewerber im direkten Vergleich','Die Tabelle und die Grafik öffnen dieselben Unternehmensdetails.',`<div class="table-wrap"><table><thead><tr><th>Unternehmen</th><th class="num">Preis</th><th class="num">Shop-Absatz</th><th class="num">Marktanteil</th><th class="num">Technologie</th><th class="num">Bekanntheit</th><th class="num">Vertrieb</th><th class="num">Gewinn</th></tr></thead><tbody>${r.competitors.map(c=>`<tr class="${c.company===1?'highlight':''}" data-company="${c.company}"><td><button class="table-button" data-company="${c.company}">${c.company===10?'Oma / U10':`U${c.company}`}${c.company===1?' · Ihr Unternehmen':''} ↗</button></td><td class="num">${euro(c.price)}</td><td class="num">${num(c.units)}</td><td class="num">${num(c.share)} %</td><td class="num">${dec(c.technology)}</td><td class="num">${num(c.awareness)} %</td><td class="num">${num(c.staff)}</td><td class="num">${teuro(D.profits[selected]?.[c.company-1])}</td></tr>`).join('')}</tbody></table></div>${foot(r,'market','Marktforschung')}`)+
      `<div class="grid equal spaced">${card('Vollständige Stückkosten','Durchschnittliche Kosten und Verteilung auf verkaufte bzw. produzierte Stücke.',costTable(r)+foot(r,'costs'))}${card('Warum funktioniert ein höherer Preis?','Beobachtungen und mögliche Erklärung sind getrennt.',row('Preis gegenüber Branchendurchschnitt',`${dec(r.decisions.price-m.priceAverage)} € / ${dec((r.decisions.price/m.priceAverage-1)*100,1)} %`)+row('Technologie U1 / Branche',`${dec(m.technology)} / ${dec(r.competitors.reduce((a,c)=>a+c.technology,0)/r.competitors.length)}`)+row('Bekanntheit U1 / Branche',`${num(m.awareness)} % / ${dec(r.competitors.reduce((a,c)=>a+c.awareness,0)/r.competitors.length,0)} %`)+`<p class="small muted spaced">Technologie, Bekanntheit, Werbung, Vertrieb und Wettbewerber beeinflussen die Nachfrage. Das Handbuch beschreibt einen relativ reaktionsarmen Preisbereich um ±5 % des Ausgangspreises 500 €. Die genaue Funktion ist nicht veröffentlicht.</p><div class="callout neutral">Das sind plausible Einflussfaktoren. Welcher einzelne Faktor wie viele Verkäufe verursacht hat, lässt sich aus diesen Berichten nicht bestimmen.</div>${src('Teilnehmerhandbuch.pdf',14,'Handbuch · Preispolitik')}`)}</div>`;
  }
  function operations(){const r=report();if(!r)return unavailable();const m=r.metrics,st=r.staff,bas=M.calculate(defaults,current),two=M.calculate({...defaults,hires:2},current);
    return heading('Produktion & Personal','Kapazität, Bestände und der Preis der verfügbaren Arbeitsleistung.')+
      `<div class="grid equal">${card('Kapazität im Betrieb','Anlage und Personal sind zwei unterschiedliche Engpässe.',`<div class="bar-row"><div class="bar-label"><span>Geplante / produzierte Zelte</span><strong>${num(m.production)} / ${num(m.capacity)}</strong></div><div class="bar-track thick"><span class="bar-fill" style="width:${Math.min(100,m.production/m.capacity*100)}%"></span></div></div><div class="bar-row"><div class="bar-label"><span>Eigenes Personal</span><strong>${num(m.productionStaff)} × ${num(m.productivity)} = ${num(m.productionStaff*m.productivity)} Zelte</strong></div><div class="bar-track thick"><span class="bar-fill" style="width:${Math.min(100,m.productionStaff*m.productivity/m.production*100)}%"></span><span class="bar-fill orange" style="width:${Math.max(0,100-m.productionStaff*m.productivity/m.production*100)}%"></span></div></div><div class="legend"><span><i style="background:#19735b"></i>Eigene Kapazität</span><span><i style="background:#d68d50"></i>Zeitarbeit ergänzt die Arbeitskapazität</span></div>${row('Zeitarbeit laut Bericht',`${dec(m.temporaryFte)} Vollzeitäquivalente`)}${row('Bezogene Fremdleistungen',teuro(m.temporaryCost))}${foot(r,'operations')}`)}${card('Zwei Einstellungen im Vergleich',`Rechenbeispiel für P${D.nextNews?.period||D.latestPeriod+1} bei unveränderter Produktion von ${num(current.metrics.production)} Zelten.`,row('Gehälter · 2 × '+euro(defaults.salary),euro(defaults.salary*2))+row('Personalnebenkosten · '+num(defaults.benefits)+' %',euro(defaults.salary*2*defaults.benefits/100))+row('Einmalige Einstellungen · 2 × '+euro(defaults.hiringCost),euro(defaults.hiringCost*2))+row('Zusätzliche Personalkosten, erste Periode',euro(defaults.salary*2*(1+defaults.benefits/100)+defaults.hiringCost*2),'emphasis')+`<div class="callout green">Gegenüber dem fortgeschriebenen Zeitarbeitsbedarf im Modell: rund <strong>${euro(bas.temporaryCost-(two.prodPayroll-bas.prodPayroll)-two.prodFees)}</strong> weniger Kosten in der ersten Periode. Voraussetzung: ${num(defaults.productivity)} Zelte pro Person, keine weitere Fluktuation und unveränderter Zeitarbeitssatz.</div>${source(current,'operations')} · ${src('P3_Infos_Periode.pdf',1,'Einstellungskosten')}`)}</div>`+
      `<div class="grid equal">${card('Anlagenbestand','Buchwert zum Ende der gewählten Periode.',`<div class="table-wrap"><table><thead><tr><th>Anlage</th><th class="num">Kapazität</th><th class="num">Buchwert</th><th class="num">Restperioden</th></tr></thead><tbody>${r.assets.map(a=>`<tr><td>Nr. ${a.id}</td><td class="num">${num(a.capacity)}</td><td class="num">${euro(a.bookValue)}</td><td class="num">${num(a.remainingLife)}</td></tr>`).join('')}</tbody></table></div>${row('Neue Anlage: Kaufpreis',euro(defaults.machinePrice))}${row('Fixkosten + Wartung pro Periode',euro(defaults.machineFixed+defaults.machineMaintenance))}${row('Abschreibung pro Periode',euro(defaults.machineDepreciation))}<p class="small muted">Kaufpreis ist eine Auszahlung und aktiviert Vermögen. Abschreibung ist Aufwand ohne erneute Auszahlung. Im Szenario werden beide getrennt gerechnet.</p>${foot(r,'operations')}`)}${card('Bestände & Materialeinkauf','Ein Zelt benötigt je eine Einheit Nylon, Gestänge und Betriebsstoffe.',row('Fertige Zelte im Endlager',num(m.inventory))+row('Bewertung Fertigwaren',euro(m.inventoryValue))+row('Nylon / Gestänge Endbestand',`${num(r.raw.closing?.[0]||0)} / ${num(r.raw.closing?.[3]||0)}`)+row('Letzter Nylonpreis',euro(r.raw.orders?.[1]))+row('Letzter Gestängepreis',euro(r.raw.orders?.[4]))+`<div class="callout">Die P3-Staffel nennt andere Preise als der P4-Bericht. Für P5 fehlt eine bestätigte aktuelle Staffel. Im Szenario können die Stückpreise oder die ausdrücklich als historisch markierte P3-Staffel gewählt werden.</div>${foot(r,'operations')}`)}</div>`+
      card('Personalbestand im Verlauf der Periode','Zeitarbeit ist zusätzlich und gehört nicht zum festen Endbestand.',`<div class="table-wrap"><table><thead><tr><th>Bereich</th><th class="num">Anfang</th><th class="num">Fluktuation</th><th class="num">Ende</th><th class="num">Gehälter</th><th class="num">Nebenkosten</th></tr></thead><tbody>${['Einkauf / Verwaltung','Vertrieb','Produktion'].map((l,i)=>`<tr><td>${l}</td><td class="num">${dec(st.start?.[i],1)}</td><td class="num">${dec(st.attrition?.[i],1)}</td><td class="num">${dec(st.end?.[i],1)}</td><td class="num">${euro(st.salary?.[i])}</td><td class="num">${euro(st.benefits?.[i])}</td></tr>`).join('')}</tbody></table></div>${foot(r,'operations')}`);
  }
  function finance(){const r=report();if(!r)return unavailable();const m=r.metrics,i=r.income,c=r.cashflow;
    const waterfall=[['Umsatz',m.revenue],['Herstellkosten des Umsatzes',-i.cogs],['Vertrieb',-i.selling],['F&E',-i.research],['Verwaltung',-i.admin],['Betriebsergebnis',m.operatingProfit],['Zinsen',-m.interest],['Steuern',-m.tax],['Überschuss',m.profit]];
    return heading('Gewinn ist nicht Kassenbestand','Ergebnisrechnung, gebundenes Kapital und die tatsächlichen Zahlungsströme.')+
      `<div class="grid equal">${card('Vom Umsatz zum Periodenergebnis','Der Wareneinsatz bezieht sich auf verkaufte Produkte.',waterfall.map(([l,v])=>row(l,teuro(v),['Betriebsergebnis','Überschuss'].includes(l)?'emphasis':'')).join('')+foot(r,'income'))}${card('Liquidität und Finanzierung','Forderungen sind bilanzieller Umsatz, aber noch kein verfügbares Geld.',row('Kasse',teuro(m.cash))+row('Forderungen aus Lieferungen',teuro(m.receivables))+row('Fertigwarenbestand',teuro(m.inventoryValue))+row('Kurzfristiger Kredit',teuro(m.credit))+row('Überziehungskredit',teuro(m.overdraft))+row('Nettoverschuldung '+info('Kurzfristiger Kredit + Überziehungskredit − Kasse; Forderungen werden nicht abgezogen.'),teuro(m.credit+m.overdraft-m.cash),'emphasis')+`<div class="callout neutral">Die bestehenden Kredite werden in der Folgeperiode zurückgezahlt. Zusätzlich ist die Dividende aus dem aktuellen Ergebnis einzuplanen: laut Handbuch grundsätzlich 50 % des Gewinns, also hier etwa ${teuro(m.profit*.5)}.</div>${foot(r,'finance')}`)}</div>`+
      `<div class="grid equal">${card('Einzahlungen und Auszahlungen','Cashflow der ausgewählten Periode, unabhängig von der Kostenrechnung.',row('Kassenanfang',teuro(c.openingCash))+row('Zahlungen aus aktueller Periode',teuro(c.currentReceipts))+row('Zahlungen aus Vorperiode',teuro(c.previousReceipts))+row('Neue Kredite inkl. Überziehung',teuro(m.credit+m.overdraft))+row('Materialeinkauf',teuro(-c.purchases))+row('Personal und Fremdleistungen',teuro(-c.personnel-c.external))+row('Sonstige Auszahlungen',teuro(-c.other))+row('Kredittilgung',teuro(-c.repayment))+row('Zinsen, Steuern und Dividende',teuro(-c.interest-c.tax-c.dividend))+row('Anlagenkauf',teuro(-c.investment))+row('Kassenende',teuro(m.cash),'emphasis')+foot(r,'finance'))}${card('Bilanz in Kürze','Endbestand der Periode.',row('Anlagevermögen',teuro(m.assets-m.receivables-m.inventoryValue-m.cash))+row('Umlaufvermögen',teuro(m.receivables+m.inventoryValue+m.cash))+row('Bilanzsumme',teuro(m.assets),'emphasis')+row('Eigenkapital',teuro(m.equity))+row('Fremdkapital',teuro(m.credit+m.overdraft))+row('Eigenkapitalquote',pct(m.equity/m.assets*100))+`<div class="callout">P4 weist rechnerisch rund ${pct(m.interest/m.credit*100)} Zinsen bezogen auf den kurzfristigen Kredit aus. Im Handbuch stehen 5 %. Ob der Unterschied aus einer Änderung oder weiteren Zinsbestandteilen stammt, ist nicht dokumentiert; der Satz ist im Szenario veränderbar.</div>${foot(r,'finance')}`)}</div>`;
  }
  const tips={price:'Shop-Preis pro Zelt. Verändert den Rechenumsatz; eine automatische Nachfragewirkung wird nicht unterstellt.',advertising:'Printwerbung als Periodenbudget. Absatzwirkung ist im Planspiel nicht quantitativ offengelegt.',promotion:'Kurzfristiges Verkaufsförderungsbudget. Die Auswirkung auf die Nachfrage muss separat geschätzt werden.',salesStaff:'Gewünschter fester Endbestand im Vertrieb. Einstellungen / Entlassungen gegenüber dem letzten Endbestand werden mitgerechnet.',research:'Nominales F&E-Budget. Faktor 1,5 in P5 erhöht die dokumentierte Wirkung, nicht automatisch den Technologieindex im Modell.',wholesale:'Zugesagte Großhandelsmenge. Wird vor dem Shop beliefert. Maximalmenge laut aktueller Nachricht.',nylon:'Bestellmenge Nylon. Fehlmengen werden im Modell zum dokumentierten Einzelbestellpreis 120 € ergänzt.',rods:'Bestellmenge Gestänge. Fehlmengen werden im Modell zum dokumentierten Einzelbestellpreis 20 € ergänzt.',production:'Gewünschte neue Produktion. Modell begrenzt sie auf die Anlagenkapazität. Fehlende Arbeitsleistung wird durch anteilige Zeitarbeit ergänzt.',newMachines:'Neue Anlagen à 500 Zelte. Kauf 55.000 €, laufend 2.500 € fix + 5.000 € Wartung; 5.000 € Abschreibung pro Periode.',sellMachines:'Anzahl bestehender Anlagen, älteste zuerst (Modellannahme). Mindestens eine bleibt. Erlös 25 % Buchwert, der übrige Buchwert ist Verlust.',hires:'Neue feste Produktionsmitarbeiter; aktuelle Basis 5. Gehalt und 20 % Nebenkosten plus einmalige Einstellungskosten.',dismissals:'Entlassungen eigener Produktionsmitarbeiter mit einmaliger Gebühr. Bestand kann nicht unter null fallen.',loan:'Neue Kreditaufnahme für die nächste Periode. Vorperiodenkredite werden zusätzlich zurückgezahlt.',planRevenue:'Planwert für potenziellen Shop-Umsatz; Großhandel bleibt ausgeschlossen. Keine Ableitung des exakten TOPSIM-Erfolgswertes.',demand:'Ihre Annahme zur potenziellen Shop-Nachfrage. Startwert rund +2 % zum letzten realen Absatz; News geben keine genaue Prozentzahl an.',attrition:'Zusätzliche angenommene Abgänge. P4 hatte einen Abgang; für P5 liegt keine bestätigte Quote vor.',nylonPrice:'Fortgeschriebener Einkaufspreis aus P4; keine bestätigte P5-Staffel. Frei veränderbare Annahme.',rodPrice:'Fortgeschriebener P4-Preis; die ältere P3-Staffel ist abweichend.',productivity:'Produktivität des letzten Berichts. P4: 215 Zelte pro Mitarbeiter und Periode. Für die Zukunft eine Annahme.',tempRate:'Aus P4 hergeleitet: Fremdleistungen / ungerundeter zusätzlicher Personalbedarf ≈ 30.000 €. Wird anteilig abgerechnet.',fgStorage:'Handbuch: 10 € je Zelt; P4-Lagerkosten entsprechen rund 8 €. Startwert 8 € als Annahme, bitte prüfen.',loanRate:'P4 rechnerisch 5,5 %; Handbuch nennt 5 %. Übernahme auf P5 ist eine Annahme.',taxRate:'P4-Steuern / Ergebnis vor Steuern = 25 %. Fortschreibung, keine bestätigte Steuerregel für P5.'};
  function field(key,label,unit='',step=1,note='',extra=''){
    const max=key==='wholesale'?defaults.wholesaleMax:(current.assets.length+scenario.newMachines-scenario.sellMachines)*defaults.machineCapacity;
    const range=['production','wholesale'].includes(key)?`<input type="range" data-range="${key}" aria-label="${label} als Regler" min="0" max="${max}" step="1" value="${Math.min(scenario[key],max)}">`:'';
    return `<div class="field ${extra}"><label for="input-${key}"><span>${label}${unit?' · '+unit:''}</span>${info(tips[key]||'Veränderbare Modellannahme. Quelle und Einschränkung siehe Modellgrundlagen.')}</label><input id="input-${key}" aria-label="${e(label)}${unit?' · '+e(unit):''}" name="${key}" type="number" min="0" step="${step}" value="${e(scenario[key])}" ${key==='wholesale'?`max="${defaults.wholesaleMax}"`:''}>${range}${note?`<div class="field-note">${note}</div>`:''}</div>`;
  }
  function newsCards(){return `<div class="news-grid"><div class="news-card"><span class="mini-label">Großhandel</span><div class="news-value">${num(defaults.wholesaleMax)} × ${euro(defaults.wholesalePrice)}</div><p>Lieferpriorität vor dem Shop. Zusätzlicher Absatz braucht verfügbare Ware.</p></div><div class="news-card"><span class="mini-label">Forschung & Entwicklung</span><div class="news-value">Wirkung × ${dec(defaults.researchFactor,1)}</div><p>Effizienteres Budget; genaue Wirkung auf Nachfrage und Index ist unbekannt.</p></div><div class="news-card"><span class="mini-label">Betriebsstoffe</span><div class="news-value">${euro(defaults.supplies)} / Zelt</div><p>${D.nextNews?.period===5?'Stabile bis leicht steigende Nachfrage. Langfristiger Ausblick trübt sich ein.':'Periodenmeldung und Annahmen vor der Entscheidung prüfen.'}</p></div></div>`;}
  function scenarioPage(){return heading('Szenario-Labor','Parameter verändern. Kapazität, Ergebnis und Liquidität gemeinsam betrachten.',tag('Rechenmodell','model')+tag('Annahmen editierbar','assumption'))+
    newsCards()+`<div class="scenario-toolbar"><button class="button" data-preset="last">Letzte Entscheidungen</button><button class="button lime" data-preset="safe">Empfehlung laden</button><button class="button" data-preset="growth">400er-Ausbau prüfen</button><input id="scenario-name" class="scenario-name" aria-label="Name des Szenarios" value="${e(scenarioName)}"><button class="button primary" id="save-scenario">Speichern</button><button class="button" id="import-scenario">Importieren</button><input id="import-file" type="file" accept="application/json,.json" hidden></div><div class="scenario-toolbar"><label for="saved-scenarios" class="small muted">Gespeicherte Szenarien</label><select id="saved-scenarios"><option value="">Auswählen …</option>${scenarios.map((x,i)=>`<option value="${i}" ${String(i)===savedIndex?'selected':''}>${e(x.name)}</option>`).join('')}</select><button class="button danger" id="delete-scenario">Auswahl löschen</button></div>`+
    `<div class="callout neutral">Nachfrage ist eine eigene Annahme. Für Preis, Werbung, F&E und Personal ist keine exakte Absatzfunktion dokumentiert. Änderungen beeinflussen hier Kosten und rechnerischen Umsatz; die geschätzte Nachfrage bleibt bis zu Ihrer Eingabe gleich.</div>`+
    `<div class="scenario-layout"><form class="scenario-controls" id="scenario-form" onsubmit="return false">${card('01 · Markt & Vertrieb','Budgets in Euro pro Periode.',`<div class="control-group">${field('price','Shop-Preis','€',1)}${field('demand','Shop-Nachfrage','Stück',1,'Annahme · unabhängig von Preisänderungen')}${field('wholesale','Großhandel','Stück',1,`Bestätigt: 0–${num(defaults.wholesaleMax)} Stück zu ${euro(defaults.wholesalePrice)}`)}${field('salesStaff','Vertriebsmitarbeiter','Personen')}${field('advertising','Printwerbung','€',1000)}${field('promotion','Verkaufsförderung','€',1000)}${field('research','F&E-Budget','€',1000)}${field('planRevenue','Plan-Shop-Umsatz','€',1000)}</div>`)}
      ${card('02 · Produktion & Einkauf','Anlagen begrenzen die Menge. Zeitarbeit füllt personelle Fehlmengen.',`<div class="control-group">${field('production','Produktionsmenge','Zelte',10)}${field('newMachines','Neue Anlagen','Anzahl')}${field('hires','Einstellungen Produktion','Personen')}${field('dismissals','Entlassungen Produktion','Personen')}${field('nylon','Bestellung Nylon','Einheiten',10)}${field('rods','Bestellung Gestänge','Einheiten',10)}${field('sellMachines','Anlagen verkaufen','Anzahl',1,'Älteste Anlagen zuerst · Modellannahme')}${field('attrition','Zusätzliche Fluktuation','Personen',1,'Unbestätigte Zukunftsannahme')}</div>`)}
      ${card('03 · Finanzierung','Kasse und Forderungen aus P'+D.latestDetailedPeriod+' werden übernommen.',`<div class="control-group">${field('loan','Neuer kurzfristiger Kredit','€',5000)}${field('cashBuffer','Gewünschter Kassenpuffer','€',1000)}</div><button class="link-button spaced" id="apply-credit">Kredit für diesen Puffer berechnen →</button>`)}
      <details><summary>Preise & Modellannahmen anpassen</summary><div class="details-body"><div class="field"><label for="input-priceMode">Einkaufspreise</label><select id="input-priceMode" name="priceMode"><option value="observed" ${scenario.priceMode==='observed'?'selected':''}>P4-Stückpreise fortschreiben (Annahme)</option><option value="historical" ${scenario.priceMode==='historical'?'selected':''}>Historische P3-Staffel (nicht P5-bestätigt)</option></select></div><div class="control-group spaced">${field('nylonPrice','Nylonpreis','€',.1)}${field('rodPrice','Gestängepreis','€',.1)}${field('supplies','Betriebsstoffe','€',.1)}${field('productivity','Produktivität','Zelte / Person')}${field('salary','Produktionsgehalt','€',100)}${field('benefits','Personalnebenkosten','%',.1)}${field('hiringCost','Einstellungskosten','€',100)}${field('dismissalCost','Entlassungskosten','€',100)}${field('tempRate','Zeitarbeitssatz','€ / FTE',100)}${field('loanRate','Kreditzins','%',.1)}${field('overdraftRate','Überziehungszins','%',.1)}${field('taxRate','Steuersatz','%',.1)}${field('receiptRate','Zahlungsquote','%',1)}${field('fgStorage','Fertigwaren-Lagerkosten','€',.1)}${field('nylonStorage','Lagerkosten Nylon','€',.1)}${field('rodStorage','Lagerkosten Gestänge','€',.1)}</div></div></details></form><div class="scenario-results" id="scenario-results"></div></div>`+
      modelGrounds();}
  function modelGrounds(){return `<details class="spaced"><summary>So rechnet das Szenario · Grenzen und Quellen</summary><div class="details-body"><div class="assumption-grid"><div><h3>Absatz & Bestand</h3><p class="small muted">Großhandel zuerst, Shop danach bis zur eingegebenen Nachfrage. Rest bleibt im Lager. Lagerbewertung im Modell zum gewichteten durchschnittlichen Herstellwert aus Anfangsbestand und neuer Fertigung.</p>${source(current,'operations')} · ${src('Teilnehmerhandbuch.pdf',15)}</div><div><h3>Aufwand & Auszahlung</h3><p class="small muted">Anlagenkauf erhöht die Auszahlung; nur die Abschreibung wird Aufwand. Herstellkosten enthalten Produktionsgehälter und Zeitarbeit bereits. Durchschnittliche historische Stückkosten werden nicht zusätzlich als Aufwand abgezogen.</p>${source(current,'costs')} · ${src('Teilnehmerhandbuch.pdf',11)}</div><div><h3>Liquidität</h3><p class="small muted">75 % des modellierten Umsatzes plus Forderungen der Vorperiode werden zu Einzahlungen. Bestehende Kredite und 50 % des letzten Gewinns als Dividende werden ausgezahlt. Fehlbeträge erzeugen einen verzinsten Überziehungskredit.</p>${src('Teilnehmerhandbuch.pdf',17)} · ${src('Teilnehmerhandbuch.pdf',19)}</div></div><div class="callout">Vereinfachungen: keine automatische Preiselastizität, keine exakte F&E- oder Bekanntheitsformel, keine bestätigte Fluktuationsquote. Kostenverteilung erfolgt näherungsweise nach Personalanteilen wie im P4-Bericht. Steuer-, Lager-, Zins-, Produktivitäts- und Materialwerte sind für die Zukunft teils fortgeschriebene Annahmen. Ein positives Modellergebnis garantiert keinen TOPSIM-Gewinn.</div></div></details>`;}
  function renderResults(){const a=M.calculate(scenario,current),noTrade=M.calculate({...scenario,wholesale:0},current),loan=M.requiredLoan(scenario,current);
    document.querySelectorAll('[data-range]').forEach(el=>{if(el.dataset.range==='production')el.max=a.capacity;el.value=Math.min(Number(el.max),scenario[el.dataset.range]);});
    const warnings=[];
    if(a.requested>a.capacity)warnings.push(`Produktionswunsch ${num(a.requested)} übersteigt die Anlagenkapazität. Modell produziert nur ${num(a.production)} Stück.`);
    if(a.lostRetail)warnings.push(`${num(a.lostRetail)} Stück der angenommenen Shop-Nachfrage bleiben unbedient. Der Großhandel erhält Priorität.`);
    if(a.temporaryFte>.01)warnings.push(`${dec(a.temporaryFte)} Zeitarbeitskräfte erforderlich: ungefähr ${euro(a.temporaryCost)} Zusatzaufwand.`);
    if(a.nylon.shortage||a.rods.shortage)warnings.push(`Materialfehlmengen: ${num(a.nylon.shortage)} Nylon / ${num(a.rods.shortage)} Gestänge. Einzelbestellungen werden zu 120 € / 20 € ergänzt.`);
    if(a.overdraft>1)warnings.push(`Geschätzter Überziehungskredit ${euro(a.overdraft)}. Prüfen Sie Kreditaufnahme und Ausgaben.`);
    if(scenario.wholesale>defaults.wholesaleMax)warnings.push(`Großhandelsmenge wird auf bestätigte ${num(defaults.wholesaleMax)} Stück begrenzt.`);
    if(scenario.priceMode==='historical')warnings.push('Die verwendete P3-Preisstaffel ist historisch und für die nächste Periode unbestätigt.');
    $('#scenario-results').innerHTML=card('Ergebnis Ihres Szenarios','Bedingte Schätzung auf Basis der sichtbaren Annahmen.',`<div class="result-grid"><div class="result-tile"><span>Umsatz gesamt</span><div class="mini-value">${teuro(a.revenue)}</div><span>Shop ${teuro(a.retailRevenue)} · Großhandel ${teuro(a.wholesaleRevenue)}</span></div><div class="result-tile"><span>Periodenüberschuss · Modell</span><div class="mini-value ${a.profit<0?'negative':'positive'}">${teuro(a.profit)}</div><span>Nach modellierten Zinsen und Steuern</span></div><div class="result-tile"><span>Voraussichtliche Kasse</span><div class="mini-value">${teuro(a.cash)}</div><span>Überziehung ${teuro(a.overdraft)}</span></div><div class="result-tile"><span>Produktion / Kapazität</span><div class="mini-value">${num(a.production)} <span>/ ${num(a.capacity)}</span></div><span>${num(a.prodStaff)} eigene Mitarbeiter + ${dec(a.temporaryFte)} FTE Zeitarbeit</span></div></div>${warnings.length?`<div class="callout">${warnings.map(w=>`<p>• ${w}</p>`).join('')}</div>`:'<div class="callout green">Unter diesen Annahmen werden die gewünschte Menge und die Shop-Nachfrage bedient. Keine automatische Überziehung erforderlich.</div>'}${row('Shop-Verkäufe / Nachfrage',`${num(a.retailSold)} / ${num(scenario.demand)}`)}${row('Großhandel tatsächlich lieferbar',`${num(a.wholesaleSold)} von ${num(a.wholesaleRequested)}`)}${row('Fertigwaren am Periodenende',`${num(a.closing)} · ${teuro(a.closingValue)}`)}${row('Kredit für '+euro(scenario.cashBuffer)+' Kassenpuffer',euro(loan))}${row('Nominales F&E-Budget / Wirkungsäquivalent',`${euro(scenario.research)} / ${euro(a.effectiveResearch)}`)}`)+
      card('Großhandel: Was ändert sich?','Vergleich bei gleicher Produktion, Personal- und Anlagenausstattung.',row('Zusätzlicher Großhandelsumsatz',sign(a.wholesaleRevenue))+row('Veränderung Shop-Umsatz',sign(a.retailRevenue-noTrade.retailRevenue))+row('Veränderung Modellgewinn',sign(a.profit-noTrade.profit),'emphasis')+`<p class="small muted">Dieser Vergleich isoliert die Abnahme vorhandener Ware. Zusätzliche Produktions- oder Investitionsentscheidungen müssen im Vergleich ganzer Szenarien betrachtet werden.</p>`)+
      `<details><summary>Ergebnisrechnung & Zahlungskalkulation öffnen</summary><div class="details-body"><h3>Aufwand</h3>${row('Verbrauchtes Material inkl. Betriebsstoffe',euro(a.materialUsed))}${row('Gehälter inkl. Nebenkosten',euro(a.payroll))}${row('Einstellungen / Entlassungen',euro(a.prodFees+a.salesFees))}${row('Zeitarbeit',euro(a.temporaryCost))}${row('Abschreibungen',euro(a.depreciation))}${row('Übrige Periodenkosten',euro(a.expenses-a.materialUsed-a.payroll-a.prodFees-a.salesFees-a.temporaryCost-a.depreciation))}${row('Aktivierung / Abbau Fertigwaren',sign(a.inventoryChange))}${row('Betriebsergebnis',euro(a.operatingProfit),'emphasis')}${row('Verlust aus Anlagenverkauf',euro(a.disposalLoss))}${row('Zinsen / Steuern',`${euro(a.interest)} / ${euro(a.tax)}`)}<h3 class="spaced">Zahlungen</h3>${row('Kasse zu Beginn',euro(current.metrics.cash))}${row('Erwartete Zahlungseingänge',euro(a.receipts))}${row('Kreditaufnahme / Überziehung',`${euro(a.loan)} / ${euro(a.overdraft)}`)}${row('Laufende Auszahlungen',euro(a.expenses-a.depreciation-a.materialUsed+a.materialCash))}${row('Rückzahlung alter Kredite',euro(a.repayment))}${row('Dividende Vorperiodenergebnis',euro(a.dividend))}${row('Anlagenkauf / Verkaufserlös',`${euro(a.capex)} / ${euro(a.saleProceeds)}`)}${row('Zinsen / Steuern',`${euro(a.interest)} / ${euro(a.tax)}`)}${row('Kassenende',euro(a.cash),'emphasis')}<div class="formula">Periodengewinn = Umsatz − Periodenaufwand + Änderung Fertigwarenbestand − Veräußerungsverlust − Zinsen − Steuern</div><p class="small muted">Die Herstellkosten werden für die Lagerbewertung verwendet. Sie werden nicht zusätzlich zu den bereits erfassten Einzelkosten abgezogen.</p></div></details>`+
      `<details><summary>Sensitivität: Shop-Nachfrage ±10 %</summary><div class="details-body"><div class="table-wrap"><table><thead><tr><th>Annahme</th><th class="num">Gewinn</th><th class="num">Kasse</th><th class="num">Unbedient</th></tr></thead><tbody>${[.9,1,1.1].map(f=>{const b=M.calculate(scenario,current,{demand:Math.round(scenario.demand*f)});return `<tr><td>${num(scenario.demand*f)} Zelte</td><td class="num">${teuro(b.profit)}</td><td class="num">${teuro(b.cash)}</td><td class="num">${num(b.lostRetail)}</td></tr>`;}).join('')}</tbody></table></div><p class="small muted">Der ±10-%-Bereich ist eine frei gewählte Belastungsprobe, keine Prognose aus den Periodeninformationen.</p></div></details>`;
  }
  function recommendations(){const a=M.calculate(presets.safe,current),b=M.calculate(presets.growth,current),s=presets.safe,g=presets.growth;
    return heading('Empfehlung für die nächste Periode','Ein Vorschlag zur Diskussion. Ihre Eingaben im Szenario-Labor werden dadurch nicht automatisch geändert.',tag('Empfehlung','model')+tag('Offene Annahmen','assumption'))+newsCards()+
      `<div class="hero-strip"><span class="hero-icon">◎</span><div class="hero-content"><strong>Erst den Personalbedarf absichern, dann den Ausbau entscheiden.</strong><p>Vorschlag: bestehende Anlagen auslasten, Zeitarbeit durch zwei feste Einstellungen ersetzen und nur den freien Absatzspielraum für Großhandel zusagen. Der 400er-Auftrag bleibt eine separat gerechnete Ausbauoption.</p></div><button class="link-button" data-preset="safe">Im Labor öffnen →</button></div>`+
      `<div class="grid three">${recCard('1','Produktion stabilisieren',`${num(s.production)} Zelte · +${num(s.hires)} Mitarbeiter`,'Keine neue Anlage. ${num(current.metrics.productionStaff+s.hires)} eigene Produktionsmitarbeiter erreichen bei ${num(s.productivity)} Stück pro Kopf ${num((current.metrics.productionStaff+s.hires)*s.productivity)} Zelte Kapazität. So lässt sich der bisherige Zeitarbeitsbedarf vermeiden.','Risiko: Fluktuation oder abweichende Produktivität erzeugt erneut Zeitarbeit.',source(current,'operations'))}${recCard('2','Großhandel begrenzen',`${num(s.wholesale)} Zelte zu ${euro(s.wholesalePrice)}`,'Die Menge wird aus verfügbarer Ware abzüglich angenommener Shop-Nachfrage und 20 Stück Reserve abgeleitet. Sie ist kein vom Planspiel ermitteltes Optimum.','Annahme: Shop-Nachfrage '+num(s.demand)+' Stück, rund +2 % zum letzten Absatz.',src(D.nextNews?.doc))}${recCard('3','Preis & Budgets halten',`${euro(s.price)} Shop-Preis`,'Print '+euro(s.advertising)+', Förderung '+euro(s.promotion)+', Vertrieb '+num(s.salesStaff)+' Personen. F&E '+euro(s.research)+' nutzt den Faktor '+dec(s.researchFactor,1)+'.','Absatzwirkungen sind unbekannt. Nachfrageannahme bei geänderten Preisen oder Budgets selbst anpassen.',source(current,'decisions'))}</div>`+
      card('Konkrete Entscheidungsvorschläge','Referenz und Ausbaualternative – alle Ergebniswerte sind Modellrechnungen.',`<div class="table-wrap"><table class="scenario-compare"><thead><tr><th>Entscheidung</th><th class="num">Bestand nutzen · Empfehlung</th><th class="num">400er-Ausbau · Alternative</th></tr></thead><tbody>${[
        ['Shop-Preis',euro(s.price),euro(g.price)],['Print / Verkaufsförderung',euro(s.advertising)+' / '+euro(s.promotion),euro(g.advertising)+' / '+euro(g.promotion)],['Vertrieb / F&E',num(s.salesStaff)+' / '+euro(s.research),num(g.salesStaff)+' / '+euro(g.research)],['Großhandelsmenge',num(s.wholesale),num(g.wholesale)],['Produktion',num(s.production),num(g.production)],['Nylon / Gestänge',num(s.nylon)+' / '+num(s.rods),num(g.nylon)+' / '+num(g.rods)],['Neue Anlagen / Verkauf',num(s.newMachines)+' / 0',num(g.newMachines)+' / 0'],['Neue Produktionsmitarbeiter',num(s.hires),num(g.hires)],['Entlassungen',num(s.dismissals),num(g.dismissals)],['Anlagenkauf · Auszahlung',euro(a.capex),euro(b.capex)],['Plan-Shop-Umsatz',euro(s.planRevenue),euro(g.planRevenue)],['Neuer Kredit · berechneter Puffer',euro(s.loan),euro(g.loan)],['Modellgewinn',teuro(a.profit),teuro(b.profit)],['Modellkasse',teuro(a.cash),teuro(b.cash)],['Angenommene Shop-Nachfrage',num(s.demand),num(g.demand)]
      ].map(([l,v,w])=>`<tr class="${l.startsWith('Modell')?'highlight':''}"><td>${l}</td><td class="num">${v}</td><td class="num">${w}</td></tr>`).join('')}</tbody></table></div><div class="callout neutral">Die Alternative zeigt unter den Basisannahmen ${sign(b.profit-a.profit)} Gewinnunterschied bei ${euro(b.capex-a.capex)} zusätzlicher Anlageninvestition. Mehr feste Mitarbeiter und ein zusätzlicher Anlagenblock bleiben nach dem Sonderauftrag bestehen. Deshalb ist ein kurzfristiger Mehrgewinn allein noch keine belastbare Ausbauentscheidung.</div><div class="scenario-toolbar"><button class="button primary" data-preset="safe">Empfehlung im Labor prüfen</button><button class="button" data-preset="growth">Ausbau im Labor prüfen</button></div>${src('Teilnehmerhandbuch.pdf',11)} · ${src('Teilnehmerhandbuch.pdf',19)} · ${src(D.nextNews?.doc)}`)+
      `<div class="callout">Vor Freigabe prüfen: aktuelle P5-Materialpreise, gültiger Kredit- und Steuersatz, geplante Fluktuation und Nachfragebandbreite. Die Empfehlung nutzt fortgeschriebene P4-Kosten und ist als begründeter Ausgangspunkt zu verstehen.</div>`+modelGrounds();}
  function recCard(i,title,value,why,risk,reference){return `<section class="card recommendation ${i==='1'?'primary':''}"><h3><span class="rec-number">0${i}</span>${title}</h3><div class="rec-value">${value}</div><p>${why}</p><div class="callout neutral">${risk}</div><div class="source-foot">${reference}</div></section>`;}
  const conflictItems=[
    ['P3-Staffel und P4-Einkaufspreise','Bei 1.500 Einheiten nennt die P3-Staffel 109 € Nylon / 17 € Gestänge. P4 weist 100 € / 16 € aus. Eine P4-Periodenmeldung fehlt. Für P5 werden P4-Preise nur als veränderbare Annahme übernommen.','P3_Infos_Periode.pdf',1],
    ['Zeitarbeit: Ausgangssatz und tatsächliche Kosten','Handbuch: 25.000 € pro Vollzeitäquivalent. Aus P4-Fremdleistungen und ungerundetem Personalbedarf ergeben sich ungefähr 30.000 €. Ursache und neuer P5-Satz sind nicht ausdrücklich dokumentiert.','Teilnehmerhandbuch.pdf',12],
    ['Zinsannahme','Handbuch: 5 % kurzfristiger Kreditzins. P4: 11.000 € Aufwand bei 200.000 € Kredit und keinem Überziehungskredit, rechnerisch 5,5 %. Die Fortschreibung ist eine Modellannahme.','Teilnehmerhandbuch.pdf',17],
    ['Lagerkosten Fertigwaren','Handbuch: 10 € je Zelt. P4: 0,39 T€ für 49 Zelte, rechnerisch rund 8 €. Im Szenario steht deshalb ein frei änderbarer Annahmewert von 8 €.','Teilnehmerhandbuch.pdf',18],
    ['Steuersatz und Produktivität','P4 lässt einen Steuersatz von 25 % erkennen und nennt 215 Zelte je Produktionsmitarbeiter. Frühere Berichte haben andere Werte. Beide P4-Werte werden für P5 nur fortgeschrieben.','P4_U1.pdf',6],
    ['Anlagenkosten: Formulierung der Vorlage','Das Formular nennt „11 Jahre“ und jährliche Fixkosten. Handbuch und Anlagenbericht spezifizieren 11 Perioden, 2.500 € sonstige Fixkosten und 5.000 € Wartung pro Periode. Das Modell folgt der detaillierten Anlagenrechnung.','Teilnehmerhandbuch.pdf',11],
    ['Umsatz im Planvergleich','Die 695.130 € der P4-Planungszeile sind 1.363 potenzielle Shop-Verkäufe × 510 €. Tatsächlich wurden 1.401 × 510 € = 714.510 € im Shop erzielt. 20.000 € Großhandelsumsatz ergeben insgesamt 734.510 €.','P4_U1.pdf',6],
    ['Fehlende Detailunterlagen','P3 ist über die Gewinnübersicht belegt, ein eigener U1-Detailbericht fehlt. P3_korrigiert_U1.pdf enthält ausdrücklich die Auswertung für Periode 2. Probe-Unterlagen werden nicht als echte Periodenergebnisse verwendet.','P4_Gewinne.pdf',1]
  ];
  function sourcesPage(){return heading('Quellen & Datenstand','Jede wichtige Zahl führt zur Fundstelle. Historische Angaben und offene Konflikte bleiben sichtbar.',tag(D.documents.length+' Dokumente')+tag('P3 nur Gewinnübersicht','assumption'))+
    `<div class="grid equal">${card('Dokumentlage',`Datenaufbereitung: ${new Date(D.generatedAt).toLocaleString('de-DE')}`,row('Letzte abgeschlossene Periode','P'+D.latestPeriod)+row('Letzter vollständiger U1-Bericht','P'+D.latestDetailedPeriod)+row('Informationen für die nächste Periode',D.nextNews?'P'+D.nextNews.period:'Fehlen')+row('Vollständige U1-Detailberichte',Object.keys(D.reports).map(p=>'P'+p).join(', '))+row('Originalunterlagen',`${D.documents.length} PDF-Dateien`)+`<p class="small muted">Neue PDFs werden durch „Aktualisieren.cmd“ im Dashboard-Ordner eingelesen. Die Zuordnung erfolgt nach Periodennummer im Dokumentinhalt, nicht allein nach Dateiname. Danach die App neu laden.</p>`)}${card('Grenzen der Simulation','Die offizielle Spielmechanik wird nicht nachgebildet.',`<p class="small muted">Die exakten Reaktionen von Kunden, Werbung und F&E sind nicht veröffentlicht. Das Szenario ist eine transparente Kosten-, Kapazitäts- und Liquiditätsrechnung unter Ihrer Nachfrageannahme.</p><p class="small muted">Fehlende Werte bleiben leer. Bei zukünftigen Berichten prüft der Import die nötigen Schlüsselwerte; strukturell anders aufgebaute PDFs benötigen gegebenenfalls eine Anpassung des Importers.</p><button class="button spaced" id="help-sources">Berechnungslogik ansehen</button>`)}</div><div class="section-divider"><h2>Offene Unterschiede und wichtige Einordnungen</h2>${tag('8 Hinweise','assumption')}</div>${conflictItems.map(([title,body,doc,p])=>`<details><summary>${title}</summary><div class="details-body"><p class="small muted">${body}</p>${src(doc,p)} · ${source(current,'operations','Aktueller U1-Bericht')}</div></details>`).join('')}<div class="section-divider"><h2>Dokumentenbibliothek</h2><span class="small muted">Original-PDF oder extrahierten Text öffnen</span></div><input id="source-search" class="search-input" type="search" placeholder="Dokument, Begriff oder Zahl suchen …" aria-label="Dokumentbibliothek durchsuchen"><div id="source-list"></div>`;}
  function renderSources(query=''){const types={report:'Echter U1-Detailbericht',news:'Periodeninformation',profits:'Gewinnübersicht',manual:'Spielregeln',form:'Vorlage / Ausgangssituation',practice:'Proberunde · aus Ist-Analyse ausgeschlossen',other:'Weitere Unterlage'};
    $('#source-list').innerHTML=D.documents.filter(d=>(d.name+' '+d.pages.join(' ')).toLocaleLowerCase('de').includes(query.toLocaleLowerCase('de'))).map(d=>`<div class="source-card"><div><h3>${e(d.name)}</h3><p>${types[d.kind]} · ${d.pages.length} Seite${d.pages.length===1?'':'n'} · Prüfsumme ${d.hash}</p></div><div class="source-actions"><button class="button source-open" data-source="${e(d.name)}" data-page="1">Fundstellen öffnen</button><a class="button" href="../../${encodeURIComponent(d.name)}" target="_blank" rel="noopener">PDF ↗</a></div></div>`).join('')||'<div class="empty">Keine Fundstelle für diesen Suchbegriff.</div>';}
  function render(){
    if(!sections.some(x=>x[0]===view))view='overview';
    $('#navigation').innerHTML=sections.map(([key,label,ic])=>`<a href="#${key}" class="nav-link ${key===view?'active':''}" ${key===view?'aria-current="page"':''}>${icon(ic)}${label}${key==='scenario'?'<small>PLAY</small>':''}</a>`).join('');
    const pages={overview,market,operations,finance,scenario:scenarioPage,recommendations,sources:sourcesPage};
    $('#content').innerHTML=pages[view]();
    if(view==='scenario')renderResults();
    if(view==='sources')renderSources();
    $('#period-select').value=selected;
    $('#period-select').disabled=['scenario','recommendations'].includes(view);
    $('#data-status').textContent=`Stand: P${D.latestPeriod} · ${D.documents.length} Unterlagen · Daten vom ${new Date(D.generatedAt).toLocaleDateString('de-DE')}`;
    document.title=`U1 · ${sections.find(s=>s[0]===view)[1]}`;
  }
  function navigate(target){if(view===target){render();return;}location.hash=target;}
  function showDialog(title,body,kicker='DETAILANSICHT'){$('#dialog-title').textContent=title;$('#dialog-kicker').textContent=kicker;$('#dialog-body').innerHTML=body;$('#detail-dialog').setAttribute('aria-labelledby','dialog-title');if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
  function sourceDialog(name,page){const doc=D.documents.find(x=>x.name===name);if(!doc)return;const p=Math.max(1,Math.min(doc.pages.length,Number(page)||1));
    showDialog(name,`<div class="source-text-select"><label for="source-page" class="small">PDF-Seite</label><select id="source-page" data-document="${e(name)}">${doc.pages.map((_,i)=>`<option value="${i+1}" ${i+1===p?'selected':''}>${i+1}</option>`).join('')}</select><a class="button" href="../../${encodeURIComponent(name)}#page=${p}" target="_blank" rel="noopener">Original-PDF öffnen ↗</a></div><p class="small muted">Extrahierter Originaltext. Tabellen können hier anders ausgerichtet sein; das PDF bleibt maßgeblich.</p><pre class="source-text">${e(doc.pages[p-1])}</pre>`,'QUELLE · ORIGINALDOKUMENT');}
  function detail(key){const r=report()||current,m=r.metrics;const content={
    revenue:['Umsatz aufgeschlüsselt',row('Shop: '+num(m.retailUnits)+' × '+euro(r.decisions.price),euro(m.retailRevenue))+row('Großhandel: '+num(r.decisions.wholesale||0)+' Stück',euro(m.wholesaleRevenue))+row('Umsatz gesamt',euro(m.revenue),'emphasis')+`<p>Der historische Großhandelspreis von ${euro(m.wholesalePriceDerived)} ist aus Umsatz abzüglich Shop-Umsatz geteilt durch Großhandelsmenge hergeleitet. Für die nächste Periode gilt die neue Meldung.</p>`+foot(r,'income')],
    profit:['Was bleibt nach Kosten?',row('Betriebsergebnis',euro(m.operatingProfit))+row('Zinsen',euro(m.interest))+row('Steuern',euro(m.tax))+row('Überschuss',euro(m.profit),'emphasis')+row('Umsatzrendite U1 / Branche',`${pct(m.margin)} / ${pct(m.marginIndustry)}`)+foot(r,'income')],
    cash:['Verfügbare Mittel & Verpflichtungen',row('Kasse',euro(m.cash))+row('Forderungen',euro(m.receivables))+row('Kredite / Überziehung',`${euro(m.credit)} / ${euro(m.overdraft)}`)+`<p>Kredite der Vorperiode und die nächste Dividendenauszahlung gehören in die Liquiditätsplanung. Forderungen sind noch kein Kassenbestand.</p>`+foot(r,'finance')],
    production:['Kapazität und Personalbedarf',row('Produktion / Anlagenkapazität',`${num(m.production)} / ${num(m.capacity)}`)+row('Eigene Mitarbeiter × Produktivität',`${num(m.productionStaff)} × ${num(m.productivity)}`)+row('Zeitarbeit',dec(m.temporaryFte)+' Vollzeitäquivalente')+row('Fremdleistungen',euro(m.temporaryCost))+foot(r,'operations')],
    market:['Marktposition von U1',row('Preis U1 / Durchschnitt',`${euro(r.decisions.price)} / ${dec(m.priceAverage)} €`)+row('Shop-Absatz',num(m.retailUnits))+row('Potenzielle Nachfrage',num(m.potentialUnits))+row('Marktanteil',pct(m.marketShare))+row('Technologie / Bekanntheit',`${dec(m.technology)} / ${num(m.awareness)} %`)+src(r.doc,7)],
    planning:['Planung: Potenzial ist der Maßstab',row('Geplanter Shop-Umsatz',euro(m.plannedRevenue))+row('Potenzieller Shop-Umsatz',euro(m.potentialRevenue))+row('Realisierter Shop-Umsatz',euro(m.retailRevenue))+row('Abweichung laut Bericht',pct(m.planningDeviation))+row('Planungsqualität',dec(m.planningQuality))+`<p>Der Bericht bewertet den Plan gegen die potenzielle Shop-Nachfrage. Großhandel ist ausgeschlossen. Die exakte Punktzahl wird hier als Berichtswert übernommen.</p>`+src('Teilnehmerhandbuch.pdf',19)+foot(r,'income')],
    costs:['Stückkosten im Detail',costTable(r)+`<p>Herstellkosten bewerten produzierte Zelte. Selbstkosten pro verkauftem Zelt enthalten zusätzlich F&E, Vertrieb und Verwaltung. Diese Durchschnittswerte sind keine belastbaren Grenzkosten eines Zusatzauftrags.</p>`+foot(r,'costs')]
    };const item=content[key];if(item)showDialog(item[0],item[1]);}
  function companyDialog(id){const r=report()||current,c=r.competitors.find(x=>x.company===+id);if(!c)return;
    showDialog(`Unternehmen ${id}${+id===1?' · U1':''}`,`<div class="detail-list">${[['Shop-Preis',euro(c.price)],['Shop-Verkäufe',num(c.units)],['Marktanteil',num(c.share)+' %'],['Technologie',dec(c.technology)],['Bekanntheit',num(c.awareness)+' %'],['Vertriebspersonal',num(c.staff)],['Printwerbung',euro(c.advertising)],['Verkaufsförderung',euro(c.promotion)],['Großhandel',num(c.wholesale??0)+' Stück'],['Periodenüberschuss',euro(D.profits[selected]?.[+id-1])]].map(([k,v])=>`<div class="detail-item"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="source-foot">${src(r.doc,c.sources.price)} ${src(r.doc,c.sources.other)} ${src(D.profitDoc)}</div>`,'MARKTFORSCHUNG · P'+selected);}
  function help(){showDialog('So nutzen Sie das Cockpit',`<p>Beginnen Sie im Überblick. Jede Kennzahlenkarte öffnet eine Detailansicht; die unterstrichenen Quellen öffnen Fundstellen im Originaltext und den PDF-Link.</p><p>Im Szenario-Labor können Sie Entscheidungen und Nachfrageannahmen verändern. Ergebnis, Kapazität und Liquidität aktualisieren sich sofort. Preis- oder Werbeänderungen erzeugen keine erfundene Nachfragewirkung.</p><p>Die Empfehlungen sind eigenständige Vorschläge. Erst „Empfehlung laden“ übernimmt sie in Ihr Szenario. Speichern legt einen lokalen Zwischenstand an; Export / Import erlaubt die Weitergabe als JSON.</p><p>Neue Dokumente: „Aktualisieren.cmd“ im Dashboard-Ordner ausführen, anschließend die App neu laden. Die Original-PDFs bleiben erhalten.</p><div class="badge-row">${tag('Berichtswert')}${tag('Rechenmodell','model')}${tag('Annahme','assumption')}</div>`,'KURZANLEITUNG');}
  function usePreset(key){savedIndex='';scenario=M.copy(key==='safe'?presets.safe:key==='growth'?presets.growth:defaults);scenarioName=key==='safe'?'Bestand nutzen':key==='growth'?'400er-Ausbau':'Letzte Entscheidungen';if(view==='scenario')render();else navigate('scenario');toast('Szenario geladen. Empfehlung bleibt ein Vorschlag.');}
  function exportScenario(){const blob=new Blob([JSON.stringify({schema:1,name:scenarioName,baselinePeriod:D.latestDetailedPeriod,decisionPeriod:D.nextNews?.period,exportedAt:new Date().toISOString(),sources:D.documents.map(d=>({name:d.name,hash:d.hash})),parameters:scenario},null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`U1-Szenario-P${D.nextNews?.period||D.latestPeriod+1}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}
  function validateImported(obj){const p=obj?.parameters;if(!p||typeof p!=='object')throw new Error('Keine Szenario-Parameter gefunden.');const clean=M.copy(defaults);for(const k of Object.keys(defaults)){if(k==='priceMode'){if(['observed','historical'].includes(p[k]))clean[k]=p[k];}else if(p[k]!=null){if(typeof p[k]!=='number'||!Number.isFinite(p[k])||p[k]<0)throw new Error(`Ungültiger Wert: ${k}`);clean[k]=p[k];}}return clean;}
  document.addEventListener('click',event=>{
    const target=event.target;
    const sourceButton=target.closest('[data-source]');if(sourceButton){sourceDialog(sourceButton.dataset.source,sourceButton.dataset.page);return;}
    const nav=target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}
    const preset=target.closest('[data-preset]');if(preset){usePreset(preset.dataset.preset);return;}
    const detailButton=target.closest('[data-detail]');if(detailButton){detail(detailButton.dataset.detail);return;}
    const cp=target.closest('[data-company]');if(cp){companyDialog(cp.dataset.company);return;}
    const period=target.closest('[data-period]');if(period){selected=+period.dataset.period;render();return;}
    if(target.closest('#save-scenario')){
      const item={name:scenarioName.trim()||'Mein Szenario',period:D.latestDetailedPeriod,parameters:M.copy(scenario)};
      const index=scenarios.findIndex(x=>x.name===item.name&&x.period===item.period);if(index>=0){scenarios[index]=item;savedIndex=String(index);}else{scenarios.push(item);savedIndex=String(scenarios.length-1);}
      scenarios=scenarios.slice(-20);try{localStorage.setItem('u1-scenarios-v1',JSON.stringify(scenarios));toast('Szenario lokal gespeichert.');render();}catch{toast('Browserspeicher nicht verfügbar. Bitte Szenario exportieren.');}
    }
    if(target.closest('#delete-scenario')){const i=$('#saved-scenarios').value;if(i===''){toast('Zuerst ein gespeichertes Szenario auswählen.');return;}scenarios.splice(+i,1);savedIndex='';try{localStorage.setItem('u1-scenarios-v1',JSON.stringify(scenarios));}catch{}render();toast('Gespeichertes Szenario gelöscht.');}
    if(target.closest('#import-scenario'))$('#import-file').click();
    if(target.closest('#apply-credit')){scenario.loan=M.requiredLoan(scenario,current);$('#input-loan').value=scenario.loan;renderResults();toast('Kredit für den gewählten Kassenpuffer angepasst.');}
    if(target.closest('#help-sources'))showDialog('Berechnungsgrundlagen',modelGrounds());
  });
  document.addEventListener('input',event=>{
    const t=event.target;
    if(t.dataset.range){scenario[t.dataset.range]=Math.max(0,Number(t.value));$('#input-'+t.dataset.range).value=scenario[t.dataset.range];renderResults();return;}
    if(t.id==='scenario-name')scenarioName=t.value;
    if(t.id==='source-search')renderSources(t.value);
    if(t.closest('#scenario-form')&&t.name&&t.type!=='select-one'){
      let value=Math.max(0,Number(t.value)||0);
      if(['hires','dismissals','newMachines','sellMachines','attrition','production','nylon','rods','salesStaff','wholesale','demand'].includes(t.name))value=Math.floor(value);
      if(t.name==='sellMachines')value=Math.min(current.assets.length-1,value);
      if(['taxRate','receiptRate','benefits'].includes(t.name))value=Math.min(100,value);
      scenario[t.name]=value;renderResults();
    }
  });
  document.addEventListener('change',async event=>{
    const t=event.target;
    if(t.id==='period-select'){selected=+t.value;render();}
    if(t.id==='source-page')sourceDialog(t.dataset.document,+t.value);
    if(t.id==='input-priceMode'){scenario.priceMode=t.value;renderResults();}
    if(t.id==='saved-scenarios'&&t.value!==''){savedIndex=t.value;const obj=scenarios[+t.value];try{scenario=validateImported(obj);scenarioName=obj.name;render();if(obj.period!==D.latestDetailedPeriod)toast('Historisches Szenario geladen: Basisperiode prüfen.');}catch(err){toast(err.message);}}
    if(t.id==='import-file'&&t.files[0]){try{const obj=JSON.parse(await t.files[0].text());scenario=validateImported(obj);scenarioName=String(obj.name||'Importiertes Szenario').slice(0,100);savedIndex='';render();toast(obj.baselinePeriod!==D.latestDetailedPeriod?'Importiert. Achtung: andere Ausgangsperiode.':'Szenario importiert.');}catch(err){toast('Import fehlgeschlagen: '+err.message);}}
  });
  document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('svg [role="button"]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(event.key==='Escape')$('#tooltip').hidden=true;});
  function showTip(target,x,y){const el=target.closest('[data-tip]');if(!el)return;const tip=$('#tooltip');tip.textContent=el.dataset.tip;tip.hidden=false;const box=tip.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(x+12,innerWidth-box.width-12))+'px';tip.style.top=Math.max(8,Math.min(y+15,innerHeight-box.height-10))+'px';}
  document.addEventListener('pointerover',event=>showTip(event.target,event.clientX,event.clientY));
  document.addEventListener('pointerout',event=>{if(event.target.closest('[data-tip]'))$('#tooltip').hidden=true;});
  document.addEventListener('focusin',event=>{const el=event.target.closest('[data-tip]');if(el){const b=el.getBoundingClientRect();showTip(el,b.left,b.bottom);}});
  document.addEventListener('focusout',()=>$('#tooltip').hidden=true);
  $('#close-dialog').addEventListener('click',()=>$('#detail-dialog').close());
  $('#detail-dialog').addEventListener('click',event=>{if(event.target===$('#detail-dialog')){const b=event.target.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)event.target.close();}});
  $('#export-button').addEventListener('click',exportScenario);$('#help-button').addEventListener('click',help);
  $('#period-select').innerHTML=D.periods.map(p=>`<option value="${p}">Periode ${p}${D.reports[p]?'':' · nur Gewinne'}</option>`).join('');
  window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'overview';render();window.scrollTo({top:0});});
  // Read-only access for validation and transparent inspection from browser developer tools.
  window.U1App={getScenario:()=>M.copy(scenario),getResult:()=>M.calculate(scenario,current),getDefaults:()=>M.copy(defaults)};
  render();
})();
